#include <string>
#include <unordered_set>
using namespace std;

class Solution {
public:
    bool queryString(string s, int n) {
        unordered_set<int> seen;
        for (int i = 0; i < s.size(); ++i) {
            if (s[i] == '0') continue;
            int val = 0;
            for (int j = i; j < s.size() && j - i < 20; ++j) {
                val = (val << 1) | (s[j] - '0');
                if (val >= 1 && val <= n) seen.insert(val);
            }
        }
        return seen.size() == n;
    }
};
